import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic target ELA features.

    The function combines a skewed quadratic component with linear and interaction terms.
    It includes a squared term, interaction terms, and a skewed component using a power function.
    The formula is: f(x) = (x[0] + x[1])**2 + 0.5 * x[0] * x[1] + 0.1 * (x[0]**3 + x[1]**3) if x[0] >= 0 and x[1] >= 0 else (x[0] + x[1])**2 + 0.5 * x[0] * x[1]
    """
    if x[0] >= 0 and x[1] >= 0:
        return (x[0] + x[1])**2 + 0.5 * x[0] * x[1] + 0.1 * (x[0]**3 + x[1]**3)
    else:
        return (x[0] + x[1])**2 + 0.5 * x[0] * x[1]
